def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def rel(path: Path) -> str:
    return path.relative_to(EXTRACTED).as_posix()


def pixels(image: Image.Image) -> dict:
    alpha = image.convert("RGBA").getchannel("A")
    bbox = alpha.getbbox()
    result = {"alpha_bbox_xyxy_exclusive": list(bbox) if bbox else None}
    if bbox:
        left, top, right, bottom = bbox
        result.update({
            "visible_width_px": right - left,
            "visible_height_px": bottom - top,
            "alpha_bottom_y_exclusive": bottom,
        })
        # A reproducible estimate, not an artist-authored pivot or collision shape.
        points = [(x, alpha.getpixel((x, bottom - 1))) for x in range(left, right)]
        weight = sum(a for _, a in points)
        result["bottom_alpha_centroid_x"] = round(sum((x + .5) * a for x, a in points) / weight, 3)
    return result


def ase_metadata(path: Path) -> dict:
    data = path.read_bytes()
    file_size, magic, frames, width, height, depth = struct.unpack_from("<I5H", data)
    if magic != 0xA5E0 or file_size != len(data):
        raise ValueError(f"Invalid Aseprite header: {path}")
    durations, tags = [], []
    offset = 128
    for _ in range(frames):
        size, frame_magic, old_chunks, duration = struct.unpack_from("<I3H", data, offset)
        new_chunks = struct.unpack_from("<I", data, offset + 12)[0]
        if frame_magic != 0xF1FA or size < 16 or offset + size > len(data):
            raise ValueError(f"Invalid Aseprite frame: {path}")
        durations.append(duration)
        pos = offset + 16
        for _ in range(new_chunks or old_chunks):
            chunk_size, kind = struct.unpack_from("<IH", data, pos)
            if chunk_size < 6 or pos + chunk_size > offset + size:
                raise ValueError(f"Invalid Aseprite chunk: {path}")
            if kind == 0x2018:
                count = struct.unpack_from("<H", data, pos + 6)[0]
                tag_pos = pos + 16
                for _ in range(count):
                    first, last, direction = struct.unpack_from("<HHB", data, tag_pos)
                    repeat = struct.unpack_from("<H", data, tag_pos + 5)[0]
                    length = struct.unpack_from("<H", data, tag_pos + 17)[0]
                    name = data[tag_pos + 19:tag_pos + 19 + length].decode("utf-8")
                    tags.append({"name": name, "from_frame": first, "to_frame": last, "frame_count": last - first + 1, "direction": direction, "repeat": repeat})
                    tag_pos += 19 + length
            pos += chunk_size
        offset += size
    for tag in tags:
        tag_durations = durations[tag["from_frame"]:tag["to_frame"] + 1]
        tag["source_duration_ms"] = sum(tag_durations)
        tag["source_frame_duration_ms_counts"] = dict(Counter(tag_durations))
    return {"canvas_px": [width, height], "depth_bpp": depth, "frame_count": frames, "duration_ms_counts": dict(Counter(durations)), "tags": tags}


def frame_groups(files: list[dict]) -> list[dict]:
    groups = defaultdict(list)
    for row in files:
        if row["kind"] == "png" and row["path"].startswith("treasure-hunters/"):
            groups[str(Path(row["path"]).parent).replace("\\", "/")].append(row)
    result = []
    for folder, rows in sorted(groups.items()):
        dimensions = sorted({tuple(row["canvas_px"]) for row in rows})
        result.append({
            "directory": folder,
            "naming": Path(folder).name,
            "png_count": len(rows),
            "canvas_px_variants": [list(x) for x in dimensions],
            "visible_height_range_px": [min(row.get("visible_height_px", 0) for row in rows), max(row.get("visible_height_px", 0) for row in rows)],
            "alpha_bottom_y_values": sorted({row.get("alpha_bottom_y_exclusive", 0) for row in rows}),
            "duration_if_animation_ms": len(rows) * 100,
            "timing_note": "100 ms comes from author default. Directory file count can also describe static props or tiles; a filename group is not by itself proof of an animation.",
        })
    return result


def contact_sheet() -> None:
    im = Image.new("RGB", (1600, 1510), "#101d29")
    d = ImageDraw.Draw(im)
    font = ImageFont.truetype("C:/Windows/Fonts/arial.ttf", 20)
    titlefont = ImageFont.truetype("C:/Windows/Fonts/arial.ttf", 30)
    tiny = ImageFont.truetype("C:/Windows/Fonts/arial.ttf", 16)
    def text(x, y, s, size=font, color="#d8e6ea"):
        d.text((x, y), s, font=size, fill=color)
    def paste(path, x, y, scale=1, crop=None):
        art = Image.open(path).convert("RGBA")
        if crop:
            art = art.crop(crop)
        art = art.resize((art.width * scale, art.height * scale), Image.Resampling.NEAREST)
        im.paste(art, (x, y), art)
    def first(pattern):
        return sorted(TH.glob(pattern))[0]
    text(24, 18, "CUTLASS WAKE / actual source art inspection", titlefont)
    text(24, 62, "Unmodified downloaded pixels. 1x and 3x NEAREST previews are labeled; scaling adds no native detail.", tiny)
    d.line((24, 94, 1576, 94), fill="#59717f")
    text(24, 110, "A / Treasure Hunters - Pixel Frog - CC0", titlefont)
    text(24, 154, "Captain: 64x40 canvas / 25-28px idle body / foot baseline y=32")
    hero = "Captain Clown Nose/Sprites/Captain Clown Nose"
    idle = first(hero + "/Captain Clown Nose without Sword/01-Idle/*.png")
    paste(idle, 30, 190)
    text(24, 238, "1x", tiny)
    states = ["09-Idle Sword", "10-Run Sword", "11-Jump Sword", "15-Attack 1", "14-Hit Sword"]
    for i, state in enumerate(states):
        folder = TH / hero / "Captain Clown Nose with Sword" / state
        files = sorted(folder.glob("*.png"))
