    text(24, 536, "Ship terrain + wall atlas: native 608x416 (1x)")
    paste(TH / "Pirate Ship/Sprites/Tilesets/Terrain and Back Wall (32x32).png", 24, 572)
    text(660, 536, "Island terrain: native 544x160 (1x)")
    paste(TH / "Palm Tree Island/Sprites/Terrain/Terrain (32x32).png", 660, 572)
    text(660, 757, "Key gaps: no named block / parry / shove animation.")
    text(660, 789, "No human melee or firearm enemy sprite in this pack.")
    text(660, 821, "Body detail is below the plan's 48-64px candidate target.")
    text(660, 853, "Use as a coherent comparison, not a silently frozen style.")
    d.line((24, 1000, 1576, 1000), fill="#59717f")
    text(24, 1018, "B / SeaHook Basic - Spriteshift - CC-BY 4.0", titlefont)
    text(24, 1060, "32px tiles, native atlas 384x192; environmental alternative")
    sea = EXTRACTED / "seahook-pack/SeaHookPack"
    paste(sea / "SeaHookTileset.png", 24, 1100)
    paste(sea / "BoatTile.png", 24, 1310)
    paste(sea / "Clouds.png", 440, 1100)
    paste(sea / "Water.png", 440, 1274)
    text(440, 1356, "All 1x; no characters supplied.", tiny)
    text(980, 1018, "C / hippo - CC-BY 3.0", titlefont)
    text(980, 1060, "40x32 cells / idle 16px body", font)
    hip = EXTRACTED / "hippo-pirate/pirate.png"
